import CryptoKit
import Foundation

/// Swift side of the pairing cryptography.
///
/// This is an independent reimplementation of `com.fliptrainer.protocol.PairingProofs` and
/// `Crypto`. The two must agree byte for byte or pairing fails on a real device with a symptom —
/// "it just won't pair" — that gives no hint where the mismatch is.
///
/// `FlipTrainerTests/PairingVectorTests.swift` asserts this implementation against
/// `test-fixtures/pairing-vectors.json`, which is generated by the Kotlin suite. If you change
/// anything here, that test tells you immediately.
enum PairingCrypto {
    static let keyLength = 32
    static let secretLength = 32
    static let nonceLength = 16
    static let macLength = 16

    // MARK: Domain separation

    /// Must match `Labels` in Crypto.kt exactly.
    private static let clientProofLabel = Data("FT1-client-proof".utf8)
    private static let serverProofLabel = Data("FT1-server-proof".utf8)
    private static let pairedKeyInfo = Data("FT1-paired-key".utf8)
    private static let envelopeLabel = Data("FT1-envelope".utf8)
    private static let discriminatorLabel = Data("FT1-discriminator".utf8)

    // MARK: Primitives

    static func hmac(key: Data, _ parts: Data...) -> Data {
        var mac = HMAC<SHA256>(key: SymmetricKey(data: key))
        for part in parts { mac.update(data: part) }
        return Data(mac.finalize())
    }

    /// RFC 5869. CryptoKit's `HKDF` is available from iOS 14, but is spelled out here so the
    /// salt/info framing is visibly identical to the Kotlin side.
    static func hkdf(inputKeyMaterial: Data, salt: Data, info: Data, length: Int = keyLength) -> Data {
        let actualSalt = salt.isEmpty ? Data(repeating: 0, count: 32) : salt
        let prk = hmac(key: actualSalt, inputKeyMaterial)

        var output = Data()
        var previous = Data()
        var counter: UInt8 = 1
        while output.count < length {
            previous = hmac(key: prk, previous, info, Data([counter]))
            output.append(previous)
            counter += 1
        }
        return output.prefix(length)
    }

    /// Constant time. `==` on `Data` short-circuits and leaks how much of a forged MAC was right.
    static func constantTimeEquals(_ a: Data, _ b: Data) -> Bool {
        guard a.count == b.count else { return false }
        var difference: UInt8 = 0
        for i in 0 ..< a.count { difference |= a[a.startIndex + i] ^ b[b.startIndex + i] }
        return difference == 0
    }

    static func randomBytes(_ count: Int) -> Data {
        var bytes = [UInt8](repeating: 0, count: count)
        _ = SecRandomCopyBytes(kSecRandomDefault, count, &bytes)
        return Data(bytes)
    }

    // MARK: Transcript

    /// Length-prefix every field before hashing.
    ///
    /// Without it, `("ab", "c")` and `("a", "bc")` produce the same transcript and a device id
    /// could be traded against a pairing id to forge a proof. Mirrors `PairingProofs.lengthPrefixed`.
    private static func lengthPrefixed(_ data: Data) -> Data {
        let n = UInt32(data.count)
        var out = Data([
            UInt8((n >> 24) & 0xFF),
            UInt8((n >> 16) & 0xFF),
            UInt8((n >> 8) & 0xFF),
            UInt8(n & 0xFF),
        ])
        out.append(data)
        return out
    }

    private static func transcript(
        deviceId: String,
        pairingId: String,
        clientNonce: Data,
        serverNonce: Data
    ) -> Data {
        var out = Data()
        out.append(lengthPrefixed(Data(deviceId.utf8)))
        out.append(lengthPrefixed(Data(pairingId.utf8)))
        out.append(lengthPrefixed(clientNonce))
        out.append(lengthPrefixed(serverNonce))
        return out
    }

    // MARK: Proofs

    static func clientProof(
        secret: Data,
        deviceId: String,
        pairingId: String,
        clientNonce: Data,
        serverNonce: Data
    ) -> Data {
        hmac(
            key: secret,
            clientProofLabel,
            transcript(deviceId: deviceId, pairingId: pairingId, clientNonce: clientNonce, serverNonce: serverNonce)
        )
    }

    static func serverProof(
        secret: Data,
        deviceId: String,
        pairingId: String,
        clientNonce: Data,
        serverNonce: Data
    ) -> Data {
        hmac(
            key: secret,
            serverProofLabel,
            transcript(deviceId: deviceId, pairingId: pairingId, clientNonce: clientNonce, serverNonce: serverNonce)
        )
    }

    static func derivePairedKey(
        secret: Data,
        deviceId: String,
        pairingId: String,
        clientNonce: Data,
        serverNonce: Data
    ) -> Data {
        var info = pairedKeyInfo
        info.append(Data(deviceId.utf8))
        info.append(Data(pairingId.utf8))
        return hkdf(
            inputKeyMaterial: secret,
            salt: clientNonce + serverNonce,
            info: info,
            length: keyLength
        )
    }

    static func discriminator(pairingId: String) -> Data {
        hmac(key: discriminatorLabel, Data(pairingId.utf8)).prefix(4)
    }

    // MARK: Envelope

    /// Mirrors `SecureChannel.mac`. Field order and widths must not drift.
    static func envelopeMac(
        key: Data,
        protocolVersion: Int,
        direction: UInt8,
        counter: UInt64,
        payload: Data
    ) -> Data {
        let version = UInt16(protocolVersion)
        var header = Data([
            UInt8((version >> 8) & 0xFF),
            UInt8(version & 0xFF),
            direction,
        ])
        for shift in stride(from: 56, through: 0, by: -8) {
            header.append(UInt8((counter >> UInt64(shift)) & 0xFF))
        }
        return hmac(key: key, envelopeLabel, header, payload).prefix(macLength)
    }
}

extension Data {
    var hexString: String { map { String(format: "%02x", $0) }.joined() }

    init?(hexString: String) {
        guard hexString.count % 2 == 0 else { return nil }
        var bytes = [UInt8]()
        bytes.reserveCapacity(hexString.count / 2)
        var index = hexString.startIndex
        while index < hexString.endIndex {
            let next = hexString.index(index, offsetBy: 2)
            guard let byte = UInt8(hexString[index ..< next], radix: 16) else { return nil }
            bytes.append(byte)
            index = next
        }
        self = Data(bytes)
    }
}
